/** Separate entry point: preserves the real OAuth, MCP and CLI broker paths. */
import production from "./index";
import { BeeBridge as BaseBridge } from "./bridge";
import { getContainer } from "@cloudflare/containers";
import type { Env } from "./types";
import { validationClosed, validationExpiry, VALIDATION_REQUEST_LIMIT, type ValidationWindow } from "./validation-window";

import { privateTrialRoute } from "./validation-routes";
type ValidationEnv = Env & ValidationWindow;

// Same single bound class, but only this isolated config exports this subclass.
// Durable quota survives isolate eviction and serializes concurrent admissions.
export class BeeBridge extends BaseBridge {
  override async fetch(request: Request): Promise<Response> {
    if (validationExpiry(this.env as ValidationEnv) === null) return validationClosed();
    return super.fetch(request);
  }

  override async startBeeBroker(id: string) {
    if (validationExpiry(this.env as ValidationEnv) === null) return { status: "error" as const, message: "validation unavailable" };
    return super.startBeeBroker(id);
  }

  override async resumeBeeBroker(id: string) {
    if (validationExpiry(this.env as ValidationEnv) === null) return { status: "error" as const, message: "validation unavailable" };
    return super.resumeBeeBroker(id);
  }

  override async clearBeeBroker(id: string) {
    // Never restart an expired Container merely to claim transient cleanup.
    // Provider teardown/revocation remains separate and must be verified.
    if (validationExpiry(this.env as ValidationEnv) === null) return { status: "error" as const, message: "validation unavailable" };
    return super.clearBeeBroker(id);
  }

  async reserveValidationRequest(): Promise<boolean> {
    const expiry = validationExpiry(this.env as ValidationEnv);
    if (expiry === null) return false;
    const admitted = await this.ctx.storage.transaction(async txn => {
      if (await txn.get<boolean>("validation:stopped")) return false;
      const count = (await txn.get<number>("validation:requests")) ?? 0;
      if (count >= VALIDATION_REQUEST_LIMIT) return false;
      await txn.put("validation:requests", count + 1);
      return true;
    });
    if (!admitted) return false;
    // Scheduling is separate from quota mutation. Failure denies this request;
    // no expensive upstream call occurs without a scheduled shutdown receipt.
    if (!(await this.ctx.storage.get<boolean>("validation:shutdown-scheduled"))) {
      await this.schedule(new Date(expiry), "expireValidation");
      await this.ctx.storage.put("validation:shutdown-scheduled", true);
    }
    return validationExpiry(this.env as ValidationEnv) !== null;
  }

  async expireValidation(): Promise<void> {
    await this.ctx.storage.put("validation:stopped", true);
    await this.destroy();
  }
}

export default {
  async fetch(request: Request, env: ValidationEnv, ctx: ExecutionContext): Promise<Response> {
    // Check before any DO/KV/Container call, including public/static routes.
    if (validationExpiry(env) === null || !env.CONSENT_SIGNING_SECRET) return validationClosed();
    const route = privateTrialRoute(request);
    if (route) return route;
    try {
      const bridge = getContainer(env.BEE_BRIDGE as DurableObjectNamespace<BeeBridge>);
      if (!(await bridge.reserveValidationRequest())) return validationClosed();
    } catch {
      return validationClosed();
    }
    const response = await production.fetch(request, env, ctx);
    // Auth pages remain behind Access or signed consent state; malformed
    // requests do not publish branded error-page copy during this private trial.
    if (response.status >= 400 && response.headers.get('Content-Type')?.includes('text/html')) return validationClosed();
    return response;
  },
};

/** Isolated hosted-auth trial only: no homepage/public-copy publication. */
export function privateTrialRoute(request: Request): Response | null {
  const url = new URL(request.url);
  const methods: Record<string, readonly string[]> = {
    '/mcp': ['GET', 'POST', 'DELETE', 'OPTIONS'],
    '/register': ['POST', 'OPTIONS'],
    '/token': ['POST', 'OPTIONS'],
    '/.well-known/oauth-authorization-server': ['GET', 'OPTIONS'],
    '/.well-known/oauth-protected-resource': ['GET', 'OPTIONS'],
    '/.well-known/oauth-protected-resource/mcp': ['GET', 'OPTIONS'],
    '/authorize/email': ['GET'],
    '/consent': ['POST'],
    '/pairing/start': ['POST'],
    '/pairing/status': ['POST'],
  };
  if (url.pathname === '/authorize' && request.method === 'GET') {
    url.pathname = '/authorize/email';
    return new Response(null, { status: 307, headers: { Location: url.toString(), 'Cache-Control': 'no-store' } });
  }
  if (Object.hasOwn(methods, url.pathname) && methods[url.pathname].includes(request.method)) return null;
  return new Response('Isolated validation unavailable', { status: 503, headers: { 'Cache-Control': 'no-store' } });
}

import { beforeEach, describe, expect, it, vi } from "vitest";
const mocks = vi.hoisted(() => ({ real: vi.fn(), reserve: vi.fn() }));
vi.mock("../src/index", () => ({ default: { fetch: mocks.real } }));
vi.mock("@cloudflare/containers", () => ({ Container: class {}, getContainer: () => ({ reserveValidationRequest: mocks.reserve }) }));
import entry from "../src/validation";
const now = "2026-09-09T05:00:00.000Z";
const env = {
  VALIDATION_STARTS_AT: now, VALIDATION_EXPIRES_AT: "2026-09-09T07:00:00.000Z",
  CONSENT_SIGNING_SECRET: "synthetic-only",

};
beforeEach(() => {
  vi.useFakeTimers(); vi.setSystemTime(Date.parse(now)); vi.clearAllMocks();
  mocks.reserve.mockResolvedValue(true); mocks.real.mockResolvedValue(new Response("Not found", { status: 404 }));

});
describe("private auth trial does not publish homepage copy", () => {
  it("keeps homepage closed even within active general validation window", async () => {
    const request = new Request("https://isolated.invalid/");
    const response = await entry.fetch(request, env as never, {} as never);
    expect(response.status).toBe(503);
    expect(mocks.real).not.toHaveBeenCalled();
    expect(mocks.reserve).not.toHaveBeenCalled();

  });
  it("expiry blocks assets before quota/storage", async () => {
    vi.setSystemTime(Date.parse(env.VALIDATION_EXPIRES_AT));
    expect((await entry.fetch(new Request("https://isolated.invalid/"), env as never, {} as never)).status).toBe(503);
    expect(mocks.reserve).not.toHaveBeenCalled();
  });
  it.each(["/mcp", "/register", "/token", "/authorize/email", "/pairing/start", "/.well-known/oauth-authorization-server"])("never turns %s errors into assets", async path => {
    const method = ["/register", "/token", "/pairing/start"].includes(path) ? "POST" : "GET";
    expect((await entry.fetch(new Request(`https://isolated.invalid${path}`, { method }), env as never, {} as never)).status).toBe(404);

  });
  it("does not serve asset fallbacks for POST", async () => {
    expect((await entry.fetch(new Request("https://isolated.invalid/", { method: "POST" }), env as never, {} as never)).status).toBe(503);

  });
  it("preserves protocol errors but never serves assets without a binding", async () => {
    mocks.real.mockResolvedValueOnce(new Response("challenge", { status: 401 }));
    expect((await entry.fetch(new Request("https://isolated.invalid/mcp"), env as never, {} as never)).status).toBe(401);
    expect((await entry.fetch(new Request("https://isolated.invalid/"), env as never, {} as never)).status).toBe(503);
  });
  it("does not publish branded malformed-auth HTML", async () => {
    mocks.real.mockResolvedValueOnce(new Response("private copy", { status: 400, headers: { "Content-Type": "text/html" } }));
    const response = await entry.fetch(new Request("https://isolated.invalid/consent", { method: "POST" }), env as never, {} as never);
    expect(response.status).toBe(503); expect(await response.text()).not.toContain("private copy");
  });
});

